export const RATIOS=[3.2,2.1,1.45,1];export const LIMITER_RPM=6400;
export const clamp=(x,a,b)=>Math.max(a,Math.min(b,Number(x)||0));
export function rpmFromSpeed(speed,gear){return Math.max(900,speed/3.6/1.8*60*3.8*RATIOS[clamp(gear,1,4)-1]);}
export function gridWeights(rpm){const keys=[900,2600,4200,5600];let lo=0;while(lo<2&&rpm>=keys[lo+1])lo++;const f=clamp((rpm-keys[lo])/(keys[lo+1]-keys[lo]),0,1);return keys.map((key,i)=>({key,gain:i===lo?Math.cos(f*Math.PI/2):i===lo+1?Math.sin(f*Math.PI/2):0,rate:clamp(rpm/key,.9,1.1)}));}
export async function createRacer({audioContext:ctx,destination,manifest,assetBaseUrl=new URL('./',import.meta.url),random=Math.random,buffers:provided,onEvent=()=>{}}={}){
 if(!ctx||!destination)throw Error('Inject the existing AudioContext and vehicle destination');if(!manifest){const r=await fetch(new URL('manifest.json',assetBaseUrl));if(!r.ok)throw Error('Private racer manifest unavailable');manifest=await r.json();}
 const buffers=new Map(provided||[]),assets=new Map(manifest.assets.map(a=>[a.id,a])),voices=new Map(),oneshots=new Set(),events=[],decodes=[];
 const input=ctx.createGain(),cut=ctx.createGain(),compressor=ctx.createDynamicsCompressor(),ceiling=ctx.createWaveShaper(),meter=ctx.createAnalyser(),master=ctx.createGain(),focus=ctx.createGain();master.gain.value=.6;compressor.threshold.value=-10;compressor.knee.value=3;compressor.ratio.value=20;compressor.attack.value=.003;compressor.release.value=.1;
 const curve=new Float32Array(4097);for(let i=0;i<curve.length;i++){const x=i/(curve.length-1)*2-1;curve[i]=Math.tanh(x*1.4)*.5/Math.tanh(1.4);}ceiling.curve=curve;ceiling.oversample='4x';input.connect(cut).connect(compressor).connect(ceiling).connect(master).connect(focus).connect(meter).connect(destination);meter.fftSize=1024;const pcm=new Float32Array(1024);let duckDb=0;
 let active=false,generation=0,lastTick=null,gear=1,rpm=900,shiftUntil=0,shiftReady=0,nextCrackle=Infinity,lastPop=null,lastCrackle=null,lastState={speedKmh:0,throttle:0,brake:0,mode:'drive'},driveMode='manual',demoAt=null,tuned=true,reference=null,loadMs=0;
 const log=e=>{events.push(e);if(events.length>800)events.shift();onEvent(e);},now=()=>ctx.currentTime;
 function ramp(p,v,tau=.035){p.setTargetAtTime(v,now(),tau);}
 function makeLoop(id){const b=buffers.get(id);if(!b)return;const s=ctx.createBufferSource(),g=ctx.createGain();s.buffer=b;s.loop=true;g.gain.value=0;s.connect(g).connect(input);s.start(now(),random()*b.duration);voices.set(id,{s,g});}
 function shot(id,{gain=1,at=now()+.01,rate=.97+random()*.06}={}){if(!active||!buffers.has(id)||oneshots.size>=16)return null;const s=ctx.createBufferSource(),g=ctx.createGain();s.buffer=buffers.get(id);s.playbackRate.value=rate;g.gain.value=gain*10**((random()*2-1)/20);s.connect(g).connect(input);const v={s,g,id};oneshots.add(v);s.onended=()=>{oneshots.delete(v);s.disconnect();g.disconnect();};s.start(at);s.stop(at+s.buffer.duration/rate+.02);log({type:'one-shot',id,at,rate,gain:g.gain.value});return v;}
 function next(ids,last){const a=ids.filter(x=>x!==last);return a[Math.floor(random()*a.length)]||ids[0];}
 function changeGear(nextGear){const previous=gear;gear=nextGear;const at=now();shiftUntil=at+.08+random()*.03;shiftReady=at+.45;shot(gear>previous?'O1_upshift':'O4_downshift_blip',{gain:.65,at:at+.01});if(gear>previous&&random()<.6){const id=next(['O2b_backfire_loud','O2c_backfire_double'],lastPop);lastPop=id;shot(id,{gain:.4,at:at+.035});}log({type:gear>previous?'upshift':'downshift',previous,gear,at,cutSeconds:shiftUntil-at,speedKmh:lastState.speedKmh});}
 async function prepare(){const start=performance.now();let i=0;const worker=async()=>{while(i<manifest.assets.length){const a=manifest.assets[i++];if(buffers.has(a.id))continue;const r=await fetch(new URL(a.file,assetBaseUrl));if(!r.ok)throw Error('Private audio unavailable '+a.id);const bytes=await r.arrayBuffer(),h=[...new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))].map(x=>x.toString(16).padStart(2,'0')).join('');if(h!==a.sha256)throw Error('Private SHA mismatch '+a.id);const b=await ctx.decodeAudioData(bytes);buffers.set(a.id,b);decodes.push({id:a.id,duration:b.duration,sampleRate:b.sampleRate});}};await Promise.all(Array.from({length:4},worker));loadMs=performance.now()-start;return snapshot();}
 async function start(){const token=++generation;await prepare();if(token!==generation)return snapshot();if(active)return snapshot();active=true;lastTick=now();for(const a of manifest.assets.filter(a=>a.loop))makeLoop(a.id);ramp(master.gain,.6);tick();return snapshot();}
 function stop(){generation++;active=false;demoAt=null;driveMode='manual';reference=null;for(const v of [...voices.values(),...oneshots]){try{v.s.stop();}catch{}v.s.disconnect();v.g.disconnect();}voices.clear();oneshots.clear();master.gain.cancelScheduledValues(now());master.gain.setValueAtTime(0,now());gear=1;rpm=900;lastState={speedKmh:0,throttle:0,brake:0,mode:'drive'};nextCrackle=Infinity;shiftUntil=shiftReady=0;return snapshot();}
function setTelemetry(update){for(const k of ['speedKmh','throttle','brake','gear','rpm'])if(k in update&&!Number.isFinite(update[k]))throw Error('Invalid telemetry '+k);if('mode' in update&&!['drive','prop','jet','hyperdrive'].includes(update.mode))throw Error('Invalid vehicle mode');lastState={...lastState,...update};lastState.speedKmh=clamp(lastState.speedKmh,0,240);lastState.throttle=clamp(lastState.throttle,0,1);lastState.brake=clamp(lastState.brake,0,1);}
 function control(mode){if(!['manual','accelerate','brake','demo'].includes(mode))throw Error('Invalid studio control');if(reference)try{reference.s.stop();}catch{}reference=null;driveMode=mode;demoAt=mode==='demo'?now():null;delete lastState.gear;delete lastState.rpm;if(mode==='demo'){gear=1;shiftReady=0;nextCrackle=Infinity;setTelemetry({speedKmh:0,throttle:0,brake:0});}return snapshot();}
 function tick(){if(!active)return;const t=now(),dt=clamp(t-(lastTick??t),0,.1);lastTick=t;
  if(driveMode==='demo'){const elapsed=t-demoAt;if(elapsed>=20){stop();log({type:'demo-complete',at:t});return;}setTelemetry({speedKmh:elapsed<1?0:elapsed<13?(elapsed-1)*12.5:150*(20-elapsed)/7,throttle:elapsed>=1&&elapsed<13?1:0,brake:elapsed>=13?1:0,mode:'drive'});}
  else if(driveMode==='accelerate')setTelemetry({speedKmh:lastState.speedKmh+dt*12.5,throttle:1,brake:0});else if(driveMode==='brake')setTelemetry({speedKmh:lastState.speedKmh-dt*22,throttle:0,brake:1});
  const externalGear=Number.isFinite(lastState.gear);if(externalGear){const g=clamp(Math.round(lastState.gear),1,4);if(g!==gear&&t>=shiftReady)changeGear(g);}rpm=Number.isFinite(lastState.rpm)?clamp(lastState.rpm,900,LIMITER_RPM):clamp(rpmFromSpeed(lastState.speedKmh,gear),900,LIMITER_RPM);
  if(!externalGear&&t>=shiftReady){if(lastState.throttle>.1&&rpm>LIMITER_RPM*.85&&gear<4)changeGear(gear+1);else if(lastState.brake>.1&&gear>1&&rpm<2200&&rpmFromSpeed(lastState.speedKmh,gear-1)<LIMITER_RPM*.85)changeGear(gear-1);rpm=clamp(rpmFromSpeed(lastState.speedKmh,gear),900,LIMITER_RPM);}
  const cutGain=t<shiftUntil?.16:1;ramp(cut.gain,cutGain,.008);const targets={};const thr=lastState.throttle,mode=lastState.mode;
  if(!reference&&mode==='drive'){gridWeights(rpm).forEach((w,i)=>{const id=['L1_idle','L2_low','L3_mid','L4_high'][i]+(!tuned&&i>=2?'_original':'');targets[id]={gain:w.gain*(.3+.7*thr),rate:w.rate*(t<shiftUntil?.93:1)};});targets.L5_overrun={gain:(lastState.speedKmh>5?(1-thr)*.65:0),rate:clamp(rpm/3600,.9,1.1)};
   const rate=(1-thr)*clamp((rpm-1600)/4800,0,1)*3.5;if(rate>0&&nextCrackle===Infinity)nextCrackle=t+.12-Math.log(Math.max(1e-8,1-random()))/rate;if(rate>0&&t>=nextCrackle){const id=next(['crackle-1','crackle-2','crackle-3','crackle-4'],lastCrackle);lastCrackle=id;shot(id,{gain:.45});nextCrackle=t+.12-Math.log(Math.max(1e-8,1-random()))/rate;}if(rate===0)nextCrackle=Infinity;
  }else if(!reference){if(mode==='prop')targets.F1_prop_loop={gain:.7,rate:.9+thr*.2};if(mode==='jet')targets.F2_jet_antigrav_loop={gain:.7,rate:.9+thr*.2};if(mode==='hyperdrive')targets.H3_tunnel_loop={gain:.6,rate:1};if(mode==='prop'||mode==='jet')targets.F3_wind_rush_loop={gain:.35*clamp(lastState.speedKmh/150,0,1),rate:1};}
  for(const [id,v] of voices){ramp(v.g.gain,targets[id]?.gain||0,.035);ramp(v.s.playbackRate,targets[id]?.rate||1,.012);} }
 function emit(e){const map={boost:'O5_boost',takeoff:'F4_takeoff',charge:'H1_charge',jump:'H2_jump',exit:'H4_exit'};if(!map[e?.type])throw Error('Unknown vehicle event');return shot(map[e.type],{gain:.7});}
 function auditionReference(id){if(!['S1_accel_upshifts','S2_brake_downshifts'].includes(id))throw Error('Not a reference');if(reference)try{reference.s.stop();}catch{}reference=shot(id,{gain:.6,rate:1});if(reference){const v=reference,cleanup=v.s.onended;v.s.onended=()=>{cleanup();if(reference===v)reference=null;};}return snapshot();}
 function snapshot(){meter.getFloatTimeDomainData(pcm);return {schema:'kfb.racer-gears/1',active,gear,rpm,speedKmh:lastState.speedKmh,throttle:lastState.throttle,brake:lastState.brake,mode:lastState.mode,driveMode,tuned,shiftUntil,loadMs,loaded:buffers.size,decoded:decodes.slice(),activeLoops:voices.size,activeOneShots:oneshots.size,rms:Math.sqrt(pcm.reduce((s,v)=>s+v*v,0)/pcm.length),limiterReductionDb:compressor.reduction,moduleCreatedAudioContexts:0,loopCrossfadeSeconds:.05,clock:'injected AudioContext.currentTime / host tick',events:events.slice(),earAcceptance:'OPEN'};}
 return {prepare,start,stop,tick,setTelemetry,control,emit,auditionReference,setTuned:value=>{tuned=!!value},createCapture:()=>{const capture=ctx.createMediaStreamDestination();meter.connect(capture);return {stream:capture.stream,disconnect:()=>meter.disconnect(capture)};},setMix:mix=>{const db=mix.musicActive||mix.dialogueActive?-3:0;if(db!==duckDb){duckDb=db;ramp(focus.gain,10**(db/20),db<0?.08:.5);}},snapshot:()=>({...snapshot(),duckDb})};
}
